function uuidv4() { return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; const v = c === 'x' ? r : (r & 0x3 | 0x8); return v.toString(16); }); }
const jobId = uuidv4();
const niche = ($env.TREND_NICHE || 'news-europe').trim();
return [{ json: { jobId, niche } }];

const ctx = $('Job Context').first().json;
const payload = { jobId: ctx.jobId, mode: 'auto', status: 'running', currentStep: 'trend-research', niche: ctx.niche };
return [{ json: { ...ctx, updateJobB64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];

const dispatchedAt = new Date($('Stamp: trend-research').first().json.dispatchedAt).getTime();
const runs = ($json.workflow_runs || []).filter(r => new Date(r.created_at).getTime() >= dispatchedAt - 5000);
runs.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
const run = runs[0] || null;
const stillWaiting = !run || run.status !== 'completed';
const succeeded = !!run && run.status === 'completed' && run.conclusion === 'success';
return [{ json: { stillWaiting, succeeded, runId: run ? run.id : null, htmlUrl: run ? run.html_url : null, conclusion: run ? run.conclusion : null } }];

